(* [comment removed for export] *)
Lemma SBMCALL M3 model3 LK3 (fx3 : FPState) R3 (ra th fbx fd : Z) :
  GM BX0 M3 model3 LK3 Aw cr ->
  getr R3 (reg 1) = Z_to_bv 64 ra -> L5.ra_ok ra -> REG0 R3 -> getr R3 (reg 10) = Z_to_bv 64 th -> getr R3 (reg 11) = Z_to_bv 64 (rr + 16) ->
  getr R3 (reg 12) = Z_to_bv 64 (F + 48) -> getr R3 (reg 13) = Z_to_bv 64 1 -> getr R3 (reg 14) = Z_to_bv 64 (spc + 168) ->
  PQATSS.binl_at RSEGS M3 rr fbx 2%nat v0 v1 -> PQATSS.binl_at RSEGS M3 (F + 32) fd 1%nat PQATSC.TEN19 d1 -> shz M3 4 ->
  L5.u64_at RSEGS M3 (spc + 168) (VV / PQATSC.TEN19) ->
  (forall (fx4 : FPState) R4 (M4 : mem) model4 LK4,
      GM BX0 M4 model4 LK4 Aw cr -> regs_preserved R3 R4 ->
      PQATSS.binl_at RSEGS M4 rr fbx 2%nat (VV mod PQATSC.TEN19) 0 -> PQATSS.binl_at RSEGS M4 (F + 32) fd 1%nat PQATSC.TEN19 d1 ->
      L5.u64_at RSEGS M4 (spc + 168) (VV / PQATSC.TEN19) -> kept (inx rr) M3 M4 ->
      srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx4 R4 ra M4 model4) K) ->
