(* [comment removed for export] *)
Lemma UNNCALL M3 model3 LK3 (fx3 : FPState) R3 (ra th fbx e0 e1 : Z) :
  GM BX0 M3 model3 LK3 Aw cr ->
  getr R3 (reg 1) = Z_to_bv 64 ra -> L5.ra_ok ra -> REG0 R3 -> getr R3 (reg 10) = Z_to_bv 64 th -> getr R3 (reg 11) = Z_to_bv 64 rr ->
  getr R3 (reg 12) = Z_to_bv 64 0 -> getr R3 (reg 13) = Z_to_bv 64 0 ->
  PQATSS.binl_at RSEGS M3 rr fbx 2%nat e0 e1 ->
  (forall (fx4 : FPState) R4 (M4 : mem) model4 LK4,
      GM BX0 M4 model4 LK4 Aw cr -> regs_preserved R3 R4 ->
      PQATSS.binl_at RSEGS M4 rr (PQATSS.wfb fbx e0 e1) (PQATSS.wlen e0 e1) e0 e1 -> kept (inx rr) M3 M4 ->
      srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx4 R4 ra M4 model4) K) ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx3 R3 UNNPC M3 model3) K.
Proof.
