Definition QN : Z := Z.lxor 0 (Z.land fb 2) / 2.
(* [comment removed for export] *)
Definition SPLN : list (Z * Z) :=
  [(V2 - 256, rr); (V2 - 320, rr / 8 + 2147450880); (V2 - 328, o / 8 + 2147450880); (V2 - 208, o); (V2 - 312, QN); (V2 - 304, 1); (V2 - 336, 0); (V2 - 288, Z.land fb 2)].
(* [comment removed for export] *)
Lemma LPN M5 model5 LK5 (fx5 : FPState) R5 (fr5 fn fd fn0 fd0 : Z) :
  GM BX0 M5 model5 LK5 Aw cr ->
  PQATSS.binl_at RSEGS M5 o fb 1%nat (VV / PQATSC.TEN19) v1 ->
  PQATSS.binl_at RSEGS M5 rr fr5 2%nat (VV mod PQATSC.TEN19) 0 ->
  L5.u8_at RSEGS M5 (F + 96) (Z.land fn 253) -> 0 <= fn <= 255 -> Z.testbit fn 0 = false ->
  L5.u8_at RSEGS M5 (F + 32) (Z.land fd 253) -> 0 <= fd <= 255 -> Z.testbit fd 0 = false ->
  PQATSS.binl_at RSEGS M5 (spc + 216) fn0 2%nat v0 v1 -> PQATSS.binl_at RSEGS M5 (spc + 184) fd0 1%nat PQATSC.TEN19 d1 ->
  L5.u32_at RSEGS M5 (spc + 180) 0 -> cells SPLN M5 ->
  REG0 R5 -> getr R5 (reg 18) = Z_to_bv 64 (F / 8 + 2147450880) -> getr R5 (reg 20) = Z_to_bv 64 (F + 32) -> getr R5 (reg 21) = Z_to_bv 64 (F + 96) ->
  getr R5 (reg 22) = Z_to_bv 64 o -> getr R5 (reg 24) = Z_to_bv 64 F -> getr R5 (reg 27) = Z_to_bv 64 F ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx5 R5 RA_RED M5 model5) K.
Proof.
