Lemma LPF M5 model5 LK5 (fx5 : FPState) R5 (fn fd fn0 : Z) :
  GM BX0 M5 model5 LK5 Aw cr ->
  PQATSS.binl_at RSEGS M5 o fb 2%nat v0 v1 ->
  PQATSS.binl_at RSEGS M5 rr fbr lenr r0 r1 ->
